    /*global Map */
    var browser_has_Map = typeof Map !== 'undefined';

    function get_sst_id(sst/*:SST*/, str/*:string*/, rev)/*:number*/ {
    	var i = 0, len = sst.length;
    	if(rev) {
    		if(browser_has_Map ? rev.has(str) : Object.prototype.hasOwnProperty.call(rev, str)) {
    			var revarr = browser_has_Map ? rev.get(str) : rev[str];
    			for(; i < revarr.length; ++i) {
    				if(sst[revarr[i]].t === str) { sst.Count ++; return revarr[i]; }
    			}
    		}
    	} else for(; i < len; ++i) {
    		if(sst[i].t === str) { sst.Count ++; return i; }
    	}
    	sst[len] = ({t:str}/*:any*/); sst.Count ++; sst.Unique ++;
    	if(rev) {
    		if(browser_has_Map) {
    			if(!rev.has(str)) rev.set(str, []);
    			rev.get(str).push(len);
    		} else {
    			if(!Object.prototype.hasOwnProperty.call(rev, str)) rev[str] = [];
    			rev[str].push(len);
    		}
    	}
    	return len;
    }

    function col_obj_w(C/*:number*/, col) {
    	var p = ({min:C+1,max:C+1}/*:any*/);
    	/* wch (chars), wpx (pixels) */
    	var wch = -1;
    	if(col.MDW) MDW = col.MDW;
    	if(col.width != null) p.customWidth = 1;
    	else if(col.wpx != null) wch = px2char(col.wpx);
    	else if(col.wch != null) wch = col.wch;
    	if(wch > -1) { p.width = char2width(wch); p.customWidth = 1; }
    	else if(col.width != null) p.width = col.width;
    	if(col.hidden) p.hidden = true;
    	if(col.level != null) { p.outlineLevel = p.level = col.level; }
    	return p;
    }

    function default_margins(margins/*:Margins*/, mode/*:?string*/) {
    	if(!margins) return;
    	var defs = [0.7, 0.7, 0.75, 0.75, 0.3, 0.3];
    	if(margins.left   == null) margins.left   = defs[0];
    	if(margins.right  == null) margins.right  = defs[1];
    	if(margins.top    == null) margins.top    = defs[2];
    	if(margins.bottom == null) margins.bottom = defs[3];
    	if(margins.header == null) margins.header = defs[4];
    	if(margins.footer == null) margins.footer = defs[5];
    }

    function get_cell_style(styles/*:Array<any>*/, cell/*:Cell*/, opts) {
    	var z = opts.revssf[cell.z != null ? cell.z : "General"];
    	var i = 0x3c, len = styles.length;
    	if(z == null && opts.ssf) {
    		for(; i < 0x188; ++i) if(opts.ssf[i] == null) {
    			SSF_load(cell.z, i);
    			// $FlowIgnore
    			opts.ssf[i] = cell.z;
    			opts.revssf[cell.z] = z = i;
    			break;
    		}
    	}
    	for(i = 0; i != len; ++i) if(styles[i].numFmtId === z) return i;
    	styles[len] = {
    		numFmtId:z,
    		fontId:0,
    		fillId:0,
    		borderId:0,
    		xfId:0,
    		applyNumberFormat:1
    	};
    	return len;
    }

    function check_ws(ws/*:Worksheet*/, sname/*:string*/, i/*:number*/) {
    	if(ws && ws['!ref']) {
    		var range = safe_decode_range(ws['!ref']);
    		if(range.e.c < range.s.c || range.e.r < range.s.r) throw new Error("Bad range (" + i + "): " + ws['!ref']);
    	}
    }

    function write_ws_xml_merges(merges/*:Array<Range>*/)/*:string*/ {
    	if(merges.length === 0) return "";
    	var o = '<mergeCells count="' + merges.length + '">';
    	for(var i = 0; i != merges.length; ++i) o += '<mergeCell ref="' + encode_range(merges[i]) + '"/>';
    	return o + '</mergeCells>';
    }
    function write_ws_xml_sheetpr(ws, wb, idx, opts, o) {
    	var needed = false;
    	var props = {}, payload = null;
    	if(opts.bookType !== 'xlsx' && wb.vbaraw) {
    		var cname = wb.SheetNames[idx];
    		try { if(wb.Workbook) cname = wb.Workbook.Sheets[idx].CodeName || cname; } catch(e) {}
    		needed = true;
    		props.codeName = utf8write(escapexml(cname));
    	}

    	if(ws && ws["!outline"]) {
    		var outlineprops = {summaryBelow:1, summaryRight:1};
    		if(ws["!outline"].above) outlineprops.summaryBelow = 0;
    		if(ws["!outline"].left) outlineprops.summaryRight = 0;
    		payload = (payload||"") + writextag('outlinePr', null, outlineprops);
    	}

    	if(!needed && !payload) return;
    	o[o.length] = (writextag('sheetPr', payload, props));
    }

    /* 18.3.1.85 sheetProtection CT_SheetProtection */
    var sheetprot_deffalse = ["objects", "scenarios", "selectLockedCells", "selectUnlockedCells"];
    var sheetprot_deftrue = [
    	"formatColumns", "formatRows", "formatCells",
    	"insertColumns", "insertRows", "insertHyperlinks",
    	"deleteColumns", "deleteRows",
    	"sort", "autoFilter", "pivotTables"
    ];
    function write_ws_xml_protection(sp)/*:string*/ {
    	// algorithmName, hashValue, saltValue, spinCount
    	var o = ({sheet:1}/*:any*/);
    	sheetprot_deffalse.forEach(function(n) { if(sp[n] != null && sp[n]) o[n] = "1"; });
    	sheetprot_deftrue.forEach(function(n) { if(sp[n] != null && !sp[n]) o[n] = "0"; });
    	/* TODO: algorithm */
    	if(sp.password) o.password = crypto_CreatePasswordVerifier_Method1(sp.password).toString(16).toUpperCase();
    	return writextag('sheetProtection', null, o);
    }
    function write_ws_xml_margins(margin)/*:string*/ {
    	default_margins(margin);
    	return writextag('pageMargins', null, margin);
    }
    function write_ws_xml_cols(ws, cols)/*:string*/ {
    	var o = ["<cols>"], col;
    	for(var i = 0; i != cols.length; ++i) {
    		if(!(col = cols[i])) continue;
    		o[o.length] = (writextag('col', null, col_obj_w(i, col)));
    	}
    	o[o.length] = "</cols>";
    	return o.join("");
    }
    function write_ws_xml_autofilter(data, ws, wb, idx)/*:string*/ {
    	var ref = typeof data.ref == "string" ? data.ref : encode_range(data.ref);
    	if(!wb.Workbook) wb.Workbook = ({Sheets:[]}/*:any*/);
    	if(!wb.Workbook.Names) wb.Workbook.Names = [];
    	var names/*: Array<any> */ = wb.Workbook.Names;
    	var range = decode_range(ref);
    	if(range.s.r == range.e.r) { range.e.r = decode_range(ws["!ref"]).e.r; ref = encode_range(range); }
    	for(var i = 0; i < names.length; ++i) {
    		var name = names[i];
    		if(name.Name != '_xlnm._FilterDatabase') continue;
    		if(name.Sheet != idx) continue;
    		name.Ref = "'" + wb.SheetNames[idx] + "'!" + ref; break;
    	}
    	if(i == names.length) names.push({ Name: '_xlnm._FilterDatabase', Sheet: idx, Ref: "'" + wb.SheetNames[idx] + "'!" + ref  });
    	return writextag("autoFilter", null, {ref:ref});
    }
    function write_ws_xml_sheetviews(ws, opts, idx, wb)/*:string*/ {
    	var sview = ({workbookViewId:"0"}/*:any*/);
    	// $FlowIgnore
    	if((((wb||{}).Workbook||{}).Views||[])[0]) sview.rightToLeft = wb.Workbook.Views[0].RTL ? "1" : "0";
    	return writextag("sheetViews", writextag("sheetView", null, sview), {});
    }

    function write_ws_xml_cell(cell/*:Cell*/, ref, ws, opts/*::, idx, wb*/)/*:string*/ {
    	if(cell.c) ws['!comments'].push([ref, cell.c]);
    	if(cell.v === undefined && typeof cell.f !== "string" || cell.t === 'z' && !cell.f) return "";
    	var vv = "";
    	var oldt = cell.t, oldv = cell.v;
    	if(cell.t !== "z") switch(cell.t) {
    		case 'b': vv = cell.v ? "1" : "0"; break;
    		case 'n': vv = ''+cell.v; break;
    		case 'e': vv = BErr[cell.v]; break;
    		case 'd':
    			if(opts && opts.cellDates) vv = parseDate(cell.v, -1).toISOString();
    			else {
    				cell = dup(cell);
    				cell.t = 'n';
    				vv = ''+(cell.v = datenum(parseDate(cell.v)));
    			}
    			if(typeof cell.z === 'undefined') cell.z = table_fmt[14];
    			break;
    		default: vv = cell.v; break;
    	}
    	var v = writetag('v', escapexml(vv)), o = ({r:ref}/*:any*/);
    	/* TODO: cell style */
    	var os = get_cell_style(opts.cellXfs, cell, opts);
    	if(os !== 0) o.s = os;
    	switch(cell.t) {
    		case 'n': break;
    		case 'd': o.t = "d"; break;
    		case 'b': o.t = "b"; break;
    		case 'e': o.t = "e"; break;
    		case 'z': break;
    		default: if(cell.v == null) { delete cell.t; break; }
    			if(cell.v.length > 32767) throw new Error("Text length must not exceed 32767 characters");
    			if(opts && opts.bookSST) {
    				v = writetag('v', ''+get_sst_id(opts.Strings, cell.v, opts.revStrings));
    				o.t = "s"; break;
    			}
    			o.t = "str"; break;
    	}
    	if(cell.t != oldt) { cell.t = oldt; cell.v = oldv; }
    	if(typeof cell.f == "string" && cell.f) {
    		var ff = cell.F && cell.F.slice(0, ref.length) == ref ? {t:"array", ref:cell.F} : null;
    		v = writextag('f', escapexml(cell.f), ff) + (cell.v != null ? v : "");
    	}
    	if(cell.l) ws['!links'].push([ref, cell.l]);
    	if(cell.D) o.cm = 1;
    	return writextag('c', v, o);
    }

    function write_ws_xml_data(ws/*:Worksheet*/, opts, idx/*:number*/, wb/*:Workbook*//*::, rels*/)/*:string*/ {
    	var o/*:Array<string>*/ = [], r/*:Array<string>*/ = [], range = safe_decode_range(ws['!ref']), cell="", ref, rr = "", cols/*:Array<string>*/ = [], R=0, C=0, rows = ws['!rows'];
    	var dense = Array.isArray(ws);
    	var params = ({r:rr}/*:any*/), row/*:RowInfo*/, height = -1;
    	for(C = range.s.c; C <= range.e.c; ++C) cols[C] = encode_col(C);
    	for(R = range.s.r; R <= range.e.r; ++R) {
    		r = [];
    		rr = encode_row(R);
    		for(C = range.s.c; C <= range.e.c; ++C) {
    			ref = cols[C] + rr;
    			var _cell = dense ? (ws[R]||[])[C]: ws[ref];
    			if(_cell === undefined) continue;
    			if((cell = write_ws_xml_cell(_cell, ref, ws, opts)) != null) r.push(cell);
    		}
    		if(r.length > 0 || (rows && rows[R])) {
    			params = ({r:rr}/*:any*/);
    			if(rows && rows[R]) {
    				row = rows[R];
    				if(row.hidden) params.hidden = 1;
    				height = -1;
    				if(row.hpx) height = px2pt(row.hpx);
    				else if(row.hpt) height = row.hpt;
    				if(height > -1) { params.ht = height; params.customHeight = 1; }
    				if(row.level) { params.outlineLevel = row.level; }
    			}
    			o[o.length] = (writextag('row', r.join(""), params));
    		}
    	}
    	if(rows) for(; R < rows.length; ++R) {
    		if(rows && rows[R]) {
    			params = ({r:R+1}/*:any*/);
    			row = rows[R];
    			if(row.hidden) params.hidden = 1;
    			height = -1;
    			if (row.hpx) height = px2pt(row.hpx);
    			else if (row.hpt) height = row.hpt;
    			if (height > -1) { params.ht = height; params.customHeight = 1; }
    			if (row.level) { params.outlineLevel = row.level; }
    			o[o.length] = (writextag('row', "", params));
    		}
    	}
    	return o.join("");
    }

    function write_ws_xml(idx/*:number*/, opts, wb/*:Workbook*/, rels)/*:string*/ {
    	var o = [XML_HEADER, writextag('worksheet', null, {
    		'xmlns': XMLNS_main[0],
    		'xmlns:r': XMLNS.r
    	})];
    	var s = wb.SheetNames[idx], sidx = 0, rdata = "";
    	var ws = wb.Sheets[s];
    	if(ws == null) ws = {};
    	var ref = ws['!ref'] || 'A1';
    	var range = safe_decode_range(ref);
    	if(range.e.c > 0x3FFF || range.e.r > 0xFFFFF) {
    		if(opts.WTF) throw new Error("Range " + ref + " exceeds format limit A1:XFD1048576");
    		range.e.c = Math.min(range.e.c, 0x3FFF);
    		range.e.r = Math.min(range.e.c, 0xFFFFF);
    		ref = encode_range(range);
    	}
    	if(!rels) rels = {};
    	ws['!comments'] = [];
    	var _drawing = [];

    	write_ws_xml_sheetpr(ws, wb, idx, opts, o);

    	o[o.length] = (writextag('dimension', null, {'ref': ref}));

    	o[o.length] = write_ws_xml_sheetviews(ws, opts, idx, wb);

    	/* TODO: store in WB, process styles */
    	if(opts.sheetFormat) o[o.length] = (writextag('sheetFormatPr', null, {
    		defaultRowHeight:opts.sheetFormat.defaultRowHeight||'16',
    		baseColWidth:opts.sheetFormat.baseColWidth||'10',
    		outlineLevelRow:opts.sheetFormat.outlineLevelRow||'7'
    	}));

    	if(ws['!cols'] != null && ws['!cols'].length > 0) o[o.length] = (write_ws_xml_cols(ws, ws['!cols']));

    	o[sidx = o.length] = '<sheetData/>';
    	ws['!links'] = [];
    	if(ws['!ref'] != null) {
    		rdata = write_ws_xml_data(ws, opts);
    		if(rdata.length > 0) o[o.length] = (rdata);
    	}
    	if(o.length>sidx+1) { o[o.length] = ('</sheetData>'); o[sidx]=o[sidx].replace("/>",">"); }

    	/* sheetCalcPr */

    	if(ws['!protect']) o[o.length] = write_ws_xml_protection(ws['!protect']);

    	/* protectedRanges */
    	/* scenarios */

    	if(ws['!autofilter'] != null) o[o.length] = write_ws_xml_autofilter(ws['!autofilter'], ws, wb, idx);

    	/* sortState */
    	/* dataConsolidate */
    	/* customSheetViews */

    	if(ws['!merges'] != null && ws['!merges'].length > 0) o[o.length] = (write_ws_xml_merges(ws['!merges']));

    	/* phoneticPr */
    	/* conditionalFormatting */
    	/* dataValidations */

    	var relc = -1, rel, rId = -1;
    	if(/*::(*/ws['!links']/*::||[])*/.length > 0) {
    		o[o.length] = "<hyperlinks>";
    		/*::(*/ws['!links']/*::||[])*/.forEach(function(l) {
    			if(!l[1].Target) return;
    			rel = ({"ref":l[0]}/*:any*/);
    			if(l[1].Target.charAt(0) != "#") {
    				rId = add_rels(rels, -1, escapexml(l[1].Target).replace(/#.*$/, ""), RELS.HLINK);
    				rel["r:id"] = "rId"+rId;
    			}
    			if((relc = l[1].Target.indexOf("#")) > -1) rel.location = escapexml(l[1].Target.slice(relc+1));
    			if(l[1].Tooltip) rel.tooltip = escapexml(l[1].Tooltip);
    			o[o.length] = writextag("hyperlink",null,rel);
    		});
    		o[o.length] = "</hyperlinks>";
    	}
    	delete ws['!links'];

    	/* printOptions */

    	if(ws['!margins'] != null) o[o.length] =  write_ws_xml_margins(ws['!margins']);

    	/* pageSetup */
    	/* headerFooter */
    	/* rowBreaks */
    	/* colBreaks */
    	/* customProperties */
    	/* cellWatches */

    	if(!opts || opts.ignoreEC || (opts.ignoreEC == (void 0))) o[o.length] = writetag("ignoredErrors", writextag("ignoredError", null, {numberStoredAsText:1, sqref:ref}));

    	/* smartTags */

    	if(_drawing.length > 0) {
    		rId = add_rels(rels, -1, "../drawings/drawing" + (idx+1) + ".xml", RELS.DRAW);
    		o[o.length] = writextag("drawing", null, {"r:id":"rId" + rId});
    		ws['!drawing'] = _drawing;
    	}

    	if(ws['!comments'].length > 0) {
    		rId = add_rels(rels, -1, "../drawings/vmlDrawing" + (idx+1) + ".vml", RELS.VML);
    		o[o.length] = writextag("legacyDrawing", null, {"r:id":"rId" + rId});
    		ws['!legacy'] = rId;
    	}

    	/* legacyDrawingHF */
    	/* picture */
    	/* oleObjects */
    	/* controls */
    	/* webPublishItems */
    	/* tableParts */
    	/* extLst */

    	if(o.length>1) { o[o.length] = ('</worksheet>'); o[1]=o[1].replace("/>",">"); }
    	return o.join("");
    }

    /* [MS-XLSB] 2.4.726 BrtRowHdr */
    function parse_BrtRowHdr(data, length) {
    	var z = ({}/*:any*/);
    	var tgt = data.l + length;
    	z.r = data.read_shift(4);
    	data.l += 4; // TODO: ixfe
    	var miyRw = data.read_shift(2);
    	data.l += 1; // TODO: top/bot padding
    	var flags = data.read_shift(1);
    	data.l = tgt;
    	if(flags & 0x07) z.level = flags & 0x07;
    	if(flags & 0x10) z.hidden = true;
    	if(flags & 0x20) z.hpt = miyRw / 20;
    	return z;
    }
    function write_BrtRowHdr(R/*:number*/, range, ws) {
    	var o = new_buf(17+8*16);
    	var row = (ws['!rows']||[])[R]||{};
    	o.write_shift(4, R);

    	o.write_shift(4, 0); /* TODO: ixfe */

    	var miyRw = 0x0140;
    	if(row.hpx) miyRw = px2pt(row.hpx) * 20;
    	else if(row.hpt) miyRw = row.hpt * 20;
    	o.write_shift(2, miyRw);

    	o.write_shift(1, 0); /* top/bot padding */

    	var flags = 0x0;
    	if(row.level) flags |= row.level;
    	if(row.hidden) flags |= 0x10;
    	if(row.hpx || row.hpt) flags |= 0x20;
    	o.write_shift(1, flags);

    	o.write_shift(1, 0); /* phonetic guide */

    	/* [MS-XLSB] 2.5.8 BrtColSpan explains the mechanism */
    	var ncolspan = 0, lcs = o.l;
    	o.l += 4;

    	var caddr = {r:R, c:0};
    	for(var i = 0; i < 16; ++i) {
    		if((range.s.c > ((i+1) << 10)) || (range.e.c < (i << 10))) continue;
    		var first = -1, last = -1;
    		for(var j = (i<<10); j < ((i+1)<<10); ++j) {
    			caddr.c = j;
    			var cell = Array.isArray(ws) ? (ws[caddr.r]||[])[caddr.c] : ws[encode_cell(caddr)];
    			if(cell) { if(first < 0) first = j; last = j; }
    		}
    		if(first < 0) continue;
    		++ncolspan;
    		o.write_shift(4, first);
    		o.write_shift(4, last);
    	}

    	var l = o.l;
    	o.l = lcs;
    	o.write_shift(4, ncolspan);
    	o.l = l;

    	return o.length > o.l ? o.slice(0, o.l) : o;
    }
    function write_row_header(ba, ws, range, R) {
    	var o = write_BrtRowHdr(R, range, ws);
    	if((o.length > 17) || (ws['!rows']||[])[R]) write_record(ba, 0x0000 /* BrtRowHdr */, o);
    }

    /* [MS-XLSB] 2.4.820 BrtWsDim */
    var parse_BrtWsDim = parse_UncheckedRfX;
    var write_BrtWsDim = write_UncheckedRfX;

    /* [MS-XLSB] 2.4.821 BrtWsFmtInfo */
    function parse_BrtWsFmtInfo(/*::data, length*/) {
    }
    //function write_BrtWsFmtInfo(ws, o) { }

    /* [MS-XLSB] 2.4.823 BrtWsProp */
    function parse_BrtWsProp(data, length) {
    	var z = {};
    	var f = data[data.l]; ++data.l;
    	z.above = !(f & 0x40);
    	z.left  = !(f & 0x80);
    	/* TODO: pull flags */
    	data.l += 18;
    	z.name = parse_XLSBCodeName(data);
    	return z;
    }
    function write_BrtWsProp(str, outl, o) {
    	if(o == null) o = new_buf(84+4*str.length);
    	var f = 0xC0;
    	if(outl) {
    		if(outl.above) f &= -65;
    		if(outl.left)  f &= -129;
    	}
    	o.write_shift(1, f);
    	for(var i = 1; i < 3; ++i) o.write_shift(1,0);
    	write_BrtColor({auto:1}, o);
    	o.write_shift(-4,-1);
    	o.write_shift(-4,-1);
    	write_XLSBCodeName(str, o);
    	return o.slice(0, o.l);
    }

    /* [MS-XLSB] 2.4.306 BrtCellBlank */
    function parse_BrtCellBlank(data) {
    	var cell = parse_XLSBCell(data);
    	return [cell];
    }
