    /* [MS-XLSB] 2.4.682 BrtMergeCell */
    var parse_BrtMergeCell = parse_UncheckedRfX;
    var write_BrtMergeCell = write_UncheckedRfX;
    /* [MS-XLSB] 2.4.107 BrtBeginMergeCells */
