    		'xmlns':      XLMLNS.ss,
    		'xmlns:o':    XLMLNS.o,
    		'xmlns:x':    XLMLNS.x,
    		'xmlns:ss':   XLMLNS.ss,
    		'xmlns:dt':   XLMLNS.dt,
    		'xmlns:html': XLMLNS.html
